  connection.sendCommand = jest.fn().mockImplementation(command => {
    if (command === 'Target.sendMessageToTarget') {
      return Promise.resolve({});
    }
    throw new Error(`${command} not implemented`);
  });

  try {
    await driver.sendCommand('Target.sendMessageToTarget', {
      message: JSON.stringify({id: 1, method: 'Network.enable'}),
      sessionId: 'F69C33F9FA07D415A913B6A55AF8B15B',
    });
    console.log('OOPIF handling test passed');
  } catch (err) {
    console.error('OOPIF handling test failed', err);
  }
}

testOOPIFHandling();
